using Godot;
using System;
public partial class MigrationScene {
 void ArtCamp(Node3D root){Color canvas=new Color(.46f,.45f,.28f);var mesh=new SurfaceTool();mesh.Begin(Mesh.PrimitiveType.Triangles);Vector3 a=new(-1.8f,0,-1.4f),b=new(1.8f,0,-1.4f),c=new(0,1.9f,-1.4f),d=new(-1.8f,0,1.4f),e=new(1.8f,0,1.4f),f=new(0,1.9f,1.4f);foreach(var p in new[]{a,c,f,a,f,d,b,e,f,b,f,c,a,b,c})mesh.AddVertex(p);mesh.GenerateNormals();root.AddChild(new MeshInstance3D{Mesh=mesh.Commit(),MaterialOverride=Material(canvas)});Tube(root,new Vector3(0,0,-1.5f),new Vector3(0,2,-1.5f),.04f,Wood);Tube(root,new Vector3(0,0,1.5f),new Vector3(0,2,1.5f),.04f,Wood);Bevel(root,new Vector3(-.7f,.11f,.2f),new Vector3(.7f,.22f,1.7f),Cloth);Ellipsoid(root,new Vector3(-.7f,.22f,-.45f),new Vector3(.3f,.13f,.21f),new Color(.66f,.60f,.42f));Box(root,new Vector3(3,.7f,0),new Vector3(1.5f,.12f,.8f),Wood,true);for(int s=-1;s<=1;s+=2)Box(root,new Vector3(3+s*.55f,.35f,0),new Vector3(.09f,.7f,.7f),Wood);Bevel(root,new Vector3(3,.88f,0),new Vector3(.23f,.26f,.23f),Steel);var lantern=new OmniLight3D{Position=new Vector3(3,1,0),LightColor=new Color(1,.68f,.29f),LightEnergy=1,OmniRange=5};root.AddChild(lantern);for(int i=0;i<9;i++)Ellipsoid(root,new Vector3(2+Mathf.Sin(i*.7f)*.6f,.15f,3+Mathf.Cos(i*.7f)*.6f),new Vector3(.18f,.13f,.16f),new Color(.38f,.39f,.32f));for(int i=0;i<3;i++)Tube(root,new Vector3(1.6f,0,2.9f+i*.12f),new Vector3(2.4f,0,3.0f+i*.12f),.08f,Ink);Bevel(root,new Vector3(2.8f,.35f,1.4f),new Vector3(.8f,.7f,.6f),Wood);}
 void EnsureStarterCamp(){string id="story/starter-camp";if(uniqueObjects.Contains(id)||Distance(player.Position,Ground(18,-8))>200)return;uniqueObjects.Add(id);var root=new Node3D{Position=Ground(18,-8),RotationDegrees=new Vector3(0,-15,0)};worldRoot.AddChild(root);ArtCamp(root);props.Add(new WorldProp{Id=id,Kind=8,Material=0,Node=root,Position=root.Position+new Vector3(3,0,0)});}
 void ArtRoad(Node3D root,int cx,int cz){for(int z=cz*64+8;z<(cz+1)*64;z+=16){double x=game.World.RouteX(z);if(x<cx*64||x>=(cx+1)*64||!game.World.Playable(x,z))continue;var p=Ground(x,z);int tier=game.World.Tier(x,z);if(tier>=3){Box(root,p+new Vector3(0,.025f,0),new Vector3(.14f,.02f,5),new Color(.65f,.56f,.33f));if((z%32+32)%32==8){var pole=Ground(x+9,z);Tube(root,pole,pole+new Vector3(0,6,0),.10f,Steel);Tube(root,pole+new Vector3(0,6,0),pole+new Vector3(-2,6,0),.06f,Steel);Bevel(root,pole+new Vector3(-2,5.9f,0),new Vector3(.6f,.12f,.3f),Steel);}}else if((z%64+64)%64==8){var post=Ground(x+7,z);Tube(root,post,post+new Vector3(0,1.7f,0),.05f,Steel);Box(root,post+new Vector3(0,1.4f,0),new Vector3(.5f,.55f,.07f),new Color(.55f,.50f,.33f));}}
 }
